import json

def dispatch(state, action):
    t = action["type"]
    if t == "click_increment":
        state["count"] += state["step"]
    elif t == "click_decrement":
        state["count"] -= state["step"]
    elif t == "click_reset":
        state["count"] = 0
    elif t == "set_step":
        state["step_input"] = action["value"]
        state["step"] = state["step_input"]
    elif t == "set_label":
        state["label_input"] = action["value"]
        state["label"] = state["label_input"].strip()
    state["is_zero"] = (state["count"] == 0)
    return state

def main():  # << START_OF_TRACE
    state = {'count': 0, 'step': 1, 'is_zero': True, 'label': 'counter', 'step_input': 1, 'label_input': 'counter'}
    state = dispatch(state, {'type': 'click_increment'})
    return state

